/* Deterministic simulation model. Times are simulation seconds; currency is dollars. */
(function(root){
const MENU={size:['Small','Medium','Large'],coffee:['Cold Brew','Original Blend','Decaf'],syrup:['Vanilla','Caramel','Mocha','Pumpkin Spice','Brown Sugar'],milk:['Almond','Oat Milk','Whole Milk','Cream','Sweet Cream'],topping:['Whipped Cream','Cinnamon','Chocolate Drizzle','Cold Foam','Caramel Drizzle'],bakery:['Croissant','Breakfast Sandwich','Cookie']};
const FIELDS=['syrup','milk','coffee','topping'];
const FILL_TARGETS={syrup:100/6,milk:50,coffee:86,topping:97};
const FILL_TOLERANCE={syrup:2,milk:3,coffee:3,topping:2};
const NAMES=['Maya','Jordan','Sophie','Alex','Noah','Ava','Leo','Zoe','Amir','Lily','Eli','Nina'];
class Cafe{
 constructor(seed=814){this.seed=seed;this.time=0;this.duration=360;this.rushIds=[];this.nextArrival=60;this.orders=[];this.id=0;this.activeId=null;this.tab='order';this.oven=null;this.helper=false;this.helperJob=null;this.helperUnlocked=false;this.costs=0;this.revenue=0;this.tips=0;this.points=0;this.served=[];this.lost=0;this.queueArea=0;this.helperCount=0;this.events=[];this.finished=false;this.addOrder()}
 rand(){this.seed=(Math.imul(this.seed,1664525)+1013904223)>>>0;return this.seed/4294967296}
 pick(a){return a[Math.floor(this.rand()*a.length)]}
 get active(){return this.orders.find(o=>o.id===this.activeId)||null}
 get profit(){return this.revenue+this.tips-this.costs}
 addOrder(){const id=++this.id,type=this.time>=300?'coffee':id===1?'combo':id%3===2?'coffee':id%3===0?'bakery':'combo';const coffee=type!=='bakery',bakery=type!=='coffee';let recipe={};if(coffee)for(let k of ['size',...FIELDS])recipe[k]=this.pick(MENU[k]);if(bakery)recipe.bakery=this.pick(MENU.bakery);if(id===1)recipe={size:'Medium',coffee:'Original Blend',syrup:'Caramel',milk:'Oat Milk',topping:'Whipped Cream',bakery:'Croissant'};let o={id,name:NAMES[(id-1)%NAMES.length],avatar:(id-1)%3,type,recipe,arrived:this.time,accepted:false,selections:{},fills:{},levels:{},lid:false,bakeryResult:null,helperDone:false,status:'waiting',price:(coffee?({Small:4,Medium:4.75,Large:5.5}[recipe.size]):0)+(bakery?{'Croissant':1.75,'Breakfast Sandwich':3.5,'Cookie':1.5}[recipe.bakery]:0)};this.orders.push(o);if(this.helperUnlocked)this.rushIds.push(id);if(!this.activeId)this.activeId=id;this.events.push({type:'arrival',name:o.name});return o}
 select(id){if(!this.orders.some(o=>o.id===id))return false;this.activeId=id;return true}
 accept(o=this.active){if(!o)return false;o.accepted=true;o.status='making';return true}
 baseLevel(k,o=this.active){let i=FIELDS.indexOf(k);return i>0?(o?.levels[FIELDS[i-1]]||0):0}
 canPour(k,o=this.active){let i=FIELDS.indexOf(k);return !!o?.accepted&&i>=0&&!!o.selections.size&&!!o.selections[k]&&FIELDS.slice(0,i).every(f=>o.fills[f]!==undefined)}
 clearFrom(k,o=this.active){if(!o)return;for(let f of FIELDS.slice(FIELDS.indexOf(k))){delete o.fills[f];delete o.levels[f]}o.lid=false}
 choose(k,v,o=this.active){if(!o||!MENU[k]?.includes(v)||!o.accepted||o.recipe[k]===undefined)return false;if(o.selections[k]===v)return true;if(FIELDS.includes(k)&&o.fills[k]!==undefined)this.clearFrom(k,o);o.selections[k]=v;return true}
 pour(k,level,o=this.active){if(!this.canPour(k,o)||!Number.isFinite(level))return false;level=Math.max(this.baseLevel(k,o),Math.min(100,level));o.levels[k]=level;let deviation=Math.max(0,Math.abs(level-FILL_TARGETS[k])-FILL_TOLERANCE[k]);o.fills[k]=Math.max(0,100-deviation*6);return true}
 retry(k,o=this.active){if(!o||!FIELDS.includes(k))return;this.clearFrom(k,o)}
 lid(o=this.active){if(o?.fills.topping!==undefined){o.lid=true;return true}return false}
 startOven(item,o=this.active){if(!o?.accepted||!o.recipe.bakery||!MENU.bakery.includes(item)||this.oven||o.bakeryResult)return false;this.oven={orderId:o.id,item,started:this.time,readyNotified:false,burnNotified:false};return true}
 get ovenElapsed(){return this.oven?this.time-this.oven.started:0}
 removeOven(){if(!this.oven)return null;let oven=this.oven,o=this.orders.find(o=>o.id===oven.orderId),t=this.ovenElapsed;let score=t<60?Math.round(t/60*55):t<=70?100:t<=80?80:t<90?55:10;let result={item:oven.item,seconds:t,score,burned:t>=90,correct:oven.item===o?.recipe.bakery};if(o)o.bakeryResult=result;this.oven=null;return result}
 remakeBakery(o=this.active){if(!o?.bakeryResult)return false;this.costs+=.6;o.bakeryResult=null;return true}
 ready(o=this.active){return !!o?.accepted&&(!o.recipe.coffee||(!!o.selections.size&&FIELDS.every(k=>o.fills[k]!==undefined)&&o.lid))&&(!o.recipe.bakery||!!o.bakeryResult)}
 scores(o=this.active){if(!o)return null;let coffeeAcc=null,bakeryAcc=null,steps={};if(o.recipe.coffee){for(let k of FIELDS)steps[k]=o.selections[k]===o.recipe[k]?(o.fills[k]??0):0;coffeeAcc=(FIELDS.reduce((s,k)=>s+steps[k],0)+(o.selections.size===o.recipe.size?100:0))/5}if(o.recipe.bakery)bakeryAcc=o.bakeryResult?.correct?o.bakeryResult.score:0;let acc=Math.round([coffeeAcc,bakeryAcc].filter(x=>x!==null).reduce((a,b)=>a+b,0)/(o.type==='combo'?2:1));let wait=this.time-o.arrived,speed=Math.max(0,100-wait/(o.recipe.bakery?210:150)*100),satisfaction=Math.round(acc*.8+speed*.2);return {steps,coffeeAccuracy:coffeeAcc,bakeryAccuracy:bakeryAcc,accuracy:acc,wait,satisfaction,speed}}
 serve(o=this.active,byHelper=false){if(!this.ready(o))return null;let s=this.scores(o);let tip=this.rand()<s.satisfaction/100?Math.round((.5+2*s.satisfaction/100)*100)/100:0;let r={...s,id:o.id,name:o.name,tip,byHelper,price:o.price};this.served.push(r);this.revenue+=o.price;this.tips+=tip;this.costs+=(o.recipe.coffee?1.15:0)+(o.recipe.bakery?.includes('Sandwich')?1.3:o.recipe.bakery ? .6 : 0);this.points+=Math.round(s.accuracy*7+s.satisfaction*3);this.orders=this.orders.filter(x=>x.id!==o.id);if(this.activeId===o.id)this.activeId=this.orders[0]?.id??null;if(byHelper)this.helperCount++;return r}
 mission(){const n=this.served.length,mean=k=>n?this.served.reduce((s,r)=>s+r[k],0)/n:0;const goals=[{label:'Serve 5 customers · average satisfaction above 80%',done:n>=5&&mean('satisfaction')>80,detail:`${n}/5 served · ${Math.round(mean('satisfaction'))}% satisfaction`},{label:'Clear the rush without a second barista',done:this.finished&&this.time>=this.duration&&!this.helper&&this.rushIds.length>0&&this.rushIds.every(id=>this.served.some(r=>r.id===id)),detail:this.helper?'Second barista hired':`${this.rushIds.filter(id=>this.served.some(r=>r.id===id)).length}/${this.rushIds.length} rush customers served · checked at shift end`},{label:'Keep average order accuracy at least 90%',done:n>0&&mean('accuracy')>=90,detail:`${Math.round(mean('accuracy'))}% accuracy`}];return {goals,points:goals.filter(g=>g.done).length*5,promoted:this.finished&&goals.every(g=>g.done)}}
 hire(){if(this.helper||!this.helperUnlocked||20+this.profit<6)return false;this.costs+=6;this.helper=true;return true}
 tick(dt){if(this.finished||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,this.duration-this.time);this.queueArea+=this.orders.length*dt;this.time+=dt;if(this.helper)this.costs+=dt*.03;if(this.time>=65&&!this.helperUnlocked){this.helperUnlocked=true;this.rushIds=this.orders.map(o=>o.id);this.events.push({type:'rush'})}while(this.time>=this.nextArrival&&this.nextArrival<this.duration){this.addOrder();this.nextArrival+=60}if(this.oven){let e=this.ovenElapsed;if(e>=60&&!this.oven.readyNotified){this.oven.readyNotified=true;this.events.push({type:'oven-ready'})}if(e>=90&&!this.oven.burnNotified){this.oven.burnNotified=true;this.events.push({type:'oven-burn'})}}if(this.helper){if(!this.helperJob){let o=this.orders.find(o=>o.id!==this.activeId&&o.recipe.coffee&&!o.helperDone&&!FIELDS.some(k=>o.fills[k]!==undefined));if(o){this.accept(o);this.helperJob={id:o.id,started:this.time}}}else if(this.time-this.helperJob.started>=22){let o=this.orders.find(o=>o.id===this.helperJob.id);if(o){for(let k of ['size',...FIELDS])o.selections[k]=o.recipe[k];for(let k of FIELDS){o.fills[k]=92;o.levels[k]=FILL_TARGETS[k]}o.lid=true;o.helperDone=true;if(!o.recipe.bakery||o.bakeryResult){this.serve(o,true);this.events.push({type:'helper-served',name:o.name})}else this.events.push({type:'helper-drink',name:o.name})}this.helperJob=null}}let departed=this.orders.filter(o=>this.time-o.arrived>240);for(let o of departed){this.lost++;this.events.push({type:'left',name:o.name});this.orders=this.orders.filter(x=>x.id!==o.id);if(this.oven?.orderId===o.id)this.oven=null;if(this.helperJob?.id===o.id)this.helperJob=null;if(this.activeId===o.id)this.activeId=this.orders[0]?.id??null}if(this.time>=this.duration){this.finished=true;this.events.push({type:'end'})}}
}
if(typeof module!=='undefined')module.exports={Cafe,MENU,FIELDS,FILL_TARGETS,FILL_TOLERANCE};root.Cafe=Cafe;root.MENU=MENU;root.FIELDS=FIELDS;root.FILL_TARGETS=FILL_TARGETS;root.FILL_TOLERANCE=FILL_TOLERANCE;
})(typeof window!=='undefined'?window:globalThis);
